import marshal, importlib.util, dis, sys

def load_code(path):
    with open(path,'rb') as f:
        data = f.read()
    print(path, 'header', data[:16])
    return marshal.loads(data[16:])

for mod in ['relativedelta','rrule','parser']:
    pyc = 'dateutil/__pycache__/%s.cpython-36.pyc' % mod
    code = load_code(pyc)
    src = open('dateutil/%s.py' % mod).read()
    code2 = compile(src, code.co_filename, 'exec')
    def cmp(a, b, path=''):
        diffs=[]
        if a.co_code != b.co_code:
            diffs.append(path+' co_code differs')
        if a.co_names != b.co_names:
            diffs.append(path+' names %r vs %r' % (a.co_names, b.co_names))
        if a.co_consts != b.co_consts:
            # find which
            for i,(x,y) in enumerate(zip(a.co_consts,b.co_consts)):
                if x!=y and not hasattr(x,'co_code'):
                    diffs.append(path+' const %d: %r vs %r' % (i,x,y))
        for x,y in zip(a.co_consts,b.co_consts):
            if hasattr(x,'co_code') and hasattr(y,'co_code'):
                diffs += cmp(x,y,path+'/'+x.co_name)
        return diffs
    d = cmp(code, code2)
    print(mod, 'DIFFS:', d[:20] if d else 'none')
