cd /dateutil && python - <<'EOF'
from dateutil.relativedelta import relativedelta as rd
from datetime import datetime, date, timedelta
import itertools, random
random.seed(1)

# 1) relativedelta + relativedelta with floats: compare effect on a datetime
base = datetime(2000,3,15,10,30,20,500000)
bad=0
for i in range(2000):
    kw1={}; kw2={}
    for k in ['days','hours','minutes','seconds','microseconds']:
        if random.random()<0.4: kw1[k]=round(random.uniform(-5,5),3)
        if random.random()<0.4: kw2[k]=round(random.uniform(-5,5),3)
    a=rd(**kw1); b=rd(**kw2)
    s=a+b
    got = base + s
    exp = (base + a) + b
    if got != exp:
        bad+=1
        if bad<8: print('SUM MISMATCH', kw1, kw2, got, exp, s)
print('sum bad', bad)

# 2) normalized() round trip
bad=0
for i in range(2000):
    kw={}
    for k in ['days','hours','minutes','seconds','microseconds']:
        if random.random()<0.5: kw[k]=round(random.uniform(-30,30),4)
    a=rd(**kw)
    n=a.normalized()
    if base + a != base + n:
        bad+=1
        if bad<8: print('NORM MISMATCH', kw, a, n, base+a, base+n)
print('norm bad', bad)
EOF
